import json
from pathlib import Path
import sys
sys.path.insert(0, "/user/user1/harbor-runs/84f6aa32b12a/prepared/incident_engine")
from resolve_worker import Query
from loader_contract import read_resolved

source = """\"\"\"Resolve a logical training record to its backing file.\"\"\"
import json
from pathlib import Path


def resolve(root, record):
    base = Path(root)
    sha = record.get("sha256")
    if not sha:
        raise FileNotFoundError("Missing sha256")
    for name in ("catalog.json", "manifest.json"):
        meta_path = base / name
        if meta_path.is_file():
            meta = json.loads(meta_path.read_text())
            for row in meta.get("rows", []):
                if row.get("sha256") == sha:
                    rel = row.get("path")
                    if rel:
                        candidate = base / rel
                        if candidate.is_file():
                            return candidate.relative_to(base)
                        alt = base / rel.replace("live/hard/", "archive/hard/")
                        if alt.is_file():
                            return alt.relative_to(base)
    pub_path = base / "PUBLIC_PROVENANCE.json"
    if pub_path.is_file():
        pub = json.loads(pub_path.read_text())
        for rel, digest in pub.get("runtime_sha256", {}).items():
            if digest == sha and rel not in ("manifest.json", "eval.jsonl"):
                candidate = base / rel
                if candidate.is_file():
                    return candidate.relative_to(base)
                alt = base / rel.replace("live/hard/", "archive/hard/")
                if alt.is_file():
                    return alt.relative_to(base)
    raise FileNotFoundError("Requested record unavailable")
"""

root = Path("/workspace/incident/dataset")
rows = json.loads((root / "manifest.json").read_text())["rows"]

for row in rows:
    q = Query(str(root))
    res = q.run(source, row)
    payload, rel = read_resolved(root, row, lambda r, rec: Query(r).run(source, rec))
    assert payload["id"] == row["id"]

# Worst-case fuel when record is missing (goes through all 3 files)
q = Query(str(root))
try:
    q.run(source, {"id": "missing", "sha256": "0"*64})
except FileNotFoundError:
    pass
print("Worst-case missing record -> remaining fuel:", q.fuel, "decoded_items:", q.decoded_items, "read_bytes:", q.read_bytes)
'

